using System.Security.Cryptography;
using Apogeu.Security.Tests.Support;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

namespace Apogeu.Operators.Tests.Support;

/// <summary>
/// The real Host in memory (WebApplicationFactory) in <c>Production</c> on an empty database of real PostgreSQL and real
/// Redis, with the demo operator turned on (<c>Operators:Demo:Enabled=true</c>, SPEC-0065 §6) and only values generated by
/// the test (ADR-0014). Nothing is removed or replaced: every hosted service runs, as on the first start in production. The
/// start is attempted at once; a failure is kept (<see cref="StartFailure"/>) for the test to report.
/// </summary>
internal sealed class ProductionApiHost : IAsyncDisposable
{
    public static readonly Uri BaseAddress = new("https://api.apogeu.test");

    private readonly WebApplicationFactory<Program> _factory;
    private readonly List<Type> _dbContextTypes;

    private ProductionApiHost(WebApplicationFactory<Program> factory, List<Type> dbContextTypes, string database, Exception? startFailure)
    {
        _factory = factory;
        _dbContextTypes = dbContextTypes;
        Database = database;
        StartFailure = startFailure;
    }

    /// <summary>Connection string of the database of this host (empty before the start).</summary>
    public string Database { get; }

    /// <summary>Why the host did not start, or <see langword="null"/> when it did.</summary>
    public Exception? StartFailure { get; }

    public static async Task<ProductionApiHost> StartAsync(string postgresServerConnectionString, string redisConnectionString, CancellationToken cancellationToken)
    {
        var database = await TestDatabase.CreateAsync(postgresServerConnectionString, cancellationToken).ConfigureAwait(false);
        var key = TestApiKey.Generate();
        var signingKey = Convert.ToBase64String(RandomNumberGenerator.GetBytes(32));
        var dbContextTypes = new List<Type>();

        var factory = new WebApplicationFactory<Program>().WithWebHostBuilder(host =>
        {
            host.UseEnvironment("Production");
            host.UseSetting("ConnectionStrings:apogeu", database);
            host.UseSetting("ConnectionStrings:redis", redisConnectionString);
            host.UseSetting("Operators:GameBaseUrl", "https://game.apogeu.test");
            host.UseSetting("Operators:Demo:Enabled", bool.TrueString);
            host.UseSetting("Operators:Demo:ApiKeys:0:Id", key.Id);
            host.UseSetting("Operators:Demo:ApiKeys:0:Secret", key.Secret);
            host.UseSetting("Security:PlayerSession:SigningKey", signingKey);
            host.UseSetting("Security:Backoffice:Authority", "https://keycloak.apogeu.test/realms/apogeu");
            host.UseSetting("Security:Backoffice:Audience", "apogeu-api");

            // Only observed: the DbContexts every module registers, to check their migrations afterwards.
            host.ConfigureTestServices(services => dbContextTypes.AddRange(services
                .Select(descriptor => descriptor.ServiceType)
                .Where(type => type.IsSubclassOf(typeof(DbContext)))
                .Distinct()));
        });

        Exception? startFailure = null;
        try
        {
            // Starts the host now: the migrations and the demo operator happen here.
            _ = factory.Server;
        }
#pragma warning disable CA1031 // The failure to start is the observation the test reports, whatever its type.
        catch (Exception exception)
#pragma warning restore CA1031
        {
            startFailure = exception;
        }

        return new ProductionApiHost(factory, dbContextTypes, database, startFailure);
    }

    public HttpClient CreateClient() =>
        _factory.CreateClient(new WebApplicationFactoryClientOptions { BaseAddress = BaseAddress, AllowAutoRedirect = false });

    /// <summary>Default schema, applied and pending migrations of every DbContext the modules register.</summary>
    public async Task<IReadOnlyList<MigrationState>> MigrationStatesAsync(CancellationToken cancellationToken)
    {
        var states = new List<MigrationState>();
        var scope = _factory.Services.CreateAsyncScope();
        await using (scope.ConfigureAwait(false))
        {
            foreach (var type in _dbContextTypes)
            {
                var context = (DbContext)scope.ServiceProvider.GetRequiredService(type);
                var applied = await context.Database.GetAppliedMigrationsAsync(cancellationToken).ConfigureAwait(false);
                var pending = await context.Database.GetPendingMigrationsAsync(cancellationToken).ConfigureAwait(false);
                states.Add(new MigrationState(type.Name, context.Model.GetDefaultSchema(), applied.ToList(), pending.ToList()));
            }
        }

        return states;
    }

    /// <summary>Runs <paramref name="action"/> with a service of the host, in a DI scope of its own.</summary>
    public async Task<T> WithServiceAsync<TService, T>(Func<TService, Task<T>> action)
        where TService : notnull
    {
        ArgumentNullException.ThrowIfNull(action);
        var scope = _factory.Services.CreateAsyncScope();
        await using (scope.ConfigureAwait(false))
        {
            return await action(scope.ServiceProvider.GetRequiredService<TService>()).ConfigureAwait(false);
        }
    }

    public ValueTask DisposeAsync() => _factory.DisposeAsync();
}
